pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount) public {
        // Bound the donation to a reasonable range to avoid huge balances
        amount = bound(amount, 1, 100 ether);
        // Deploy a recipient helper that tracks received ether
        RecipientTracker recipient = new RecipientTracker();
        // Fund the contract with a donation from anyone
        vm.deal(address(0x1), amount);
        vm.prank(address(0x1));
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "donation failed");
        uint256 balanceBefore = address(c).balance;
        // Owner (address(this)) withdraws all to the tracked recipient
        vm.prank(address(this));
        try c.withdrawAll(address(recipient)) {} catch {}
        // The rule: if the call did not revert (which it shouldn't for owner),
        // the tracked balance of the recipient must equal the pre-withdrawal balance.
        assertEq(recipient.received(), balanceBefore, "recipient should receive full contract balance");
    }
}

contract RecipientTracker {
    uint256 public received;
    receive() external payable {
        received += msg.value;
    }
}

