        c.f{value: _amount}();
        uint256 balBefore = _recipient.balance;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", _recipient));
        require(ok);
        uint256 balAfter = _recipient.balance;
        assert(balAfter - balBefore == address(c).balance + _amount);
    }
}

